CREATE TABLE "ConsentRecord" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"contactId" UUID NOT NULL,"channel" TEXT NOT NULL DEFAULT 'WHATSAPP',"status" TEXT NOT NULL,"source" TEXT NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),CONSTRAINT "ConsentRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MessageTemplate" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"externalTemplateId" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"language" TEXT NOT NULL,"status" TEXT NOT NULL,"components" JSONB NOT NULL,"syncedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MessageTemplate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AISuggestion" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"opportunityId" UUID NOT NULL,"analysisId" UUID,"content" TEXT NOT NULL,"editedContent" TEXT,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AISuggestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OutboundMessage" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"conversationId" UUID NOT NULL,"opportunityId" UUID,"suggestionId" UUID,"idempotencyKey" TEXT NOT NULL,"currentPolicyDecisionId" UUID,"status" TEXT NOT NULL DEFAULT 'PENDING_APPROVAL',"content" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"templateId" UUID,"externalMessageId" TEXT,"scheduledAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OutboundMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PolicyDecision" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"outboundMessageId" UUID,"decision" TEXT NOT NULL,"reasons" JSONB NOT NULL,"policyVersion" TEXT NOT NULL,"contextSnapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PolicyDecision_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OutboundMessageEvent" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"outboundMessageId" UUID NOT NULL,"externalEventId" TEXT NOT NULL,"status" TEXT NOT NULL,"payload" JSONB,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OutboundMessageEvent_pkey" PRIMARY KEY ("id"));
